interface ICounter { int Value { get; } void Inc(); }

struct Counter : ICounter
{
    public int Value { get; private set; }
    void ICounter.Inc() => Value++;   // явная реализация
}

var c = new Counter();
// c.Inc();            // ошибка CS1061
((ICounter)c).Inc();   // упаковка: выросла копия, c.Value == 0
ICounter box = c;      // ещё одна коробка
box.Inc();             // box.Value == 1, а c.Value == 0

