static void Bump<T>(ref T x) where T : ICounter => x.Inc();
static void BumpBoxed(ICounter x) => x.Inc();

var c = new Counter();
Bump(ref c);     // без коробки: c.Value == 1
BumpBoxed(c);    // коробка: c.Value всё ещё 1
